<form method="get" class="schedule-filters" action="<?= $template==='agenda' ? '/horarios/agenda' : ($template==='blocks' ? '/bloqueos' : '/horarios') ?>">
<div><label for="medico" class="form-label">Médico</label><select class="form-select" name="medico" id="medico"><option value="">Todos los permitidos</option><?php foreach($doctors as $m): ?><option value="<?= $escape($m['id_medico']) ?>" <?= $doctorFilter===(int)$m['id_medico'] ? 'selected' : '' ?>><?= $escape($m['apellidos'].', '.$m['nombres']) ?></option><?php endforeach; ?></select></div>
<div><label for="especialidad" class="form-label">Especialidad</label><select class="form-select" name="especialidad" id="especialidad"><option value="">Todas</option><?php foreach($specialties as $e): ?><option value="<?= $escape($e['id_especialidad']) ?>" <?= $specialtyFilter===(int)$e['id_especialidad'] ? 'selected' : '' ?>><?= $escape($e['nombre']) ?></option><?php endforeach; ?></select></div>
<div><label for="dia" class="form-label">Día habitual</label><select class="form-select" name="dia" id="dia"><option value="">Todos</option><?php foreach(\Clinica\Services\ScheduleValidator::DAYS as $key=>$label): ?><option value="<?= $key ?>" <?= $dayFilter===$key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div>
<?php if($template==='agenda'): ?><div><label for="semana" class="form-label">Fecha de referencia</label><input class="form-control" type="date" id="semana" name="semana" required value="<?= $escape($weekDate) ?>"></div><?php endif; ?>
<button class="btn btn-clinic align-self-end" type="submit">Aplicar filtros</button><a class="btn btn-outline-secondary align-self-end" href="<?= $template==='agenda' ? '/horarios/agenda' : ($template==='blocks' ? '/bloqueos' : '/horarios') ?>">Limpiar</a></form>

